SELECT *, NTILE(4) OVER (PARTITION BY category ORDER BY price, id) AS price_bucket, LAST_VALUE(cost) IGNORE NULLS OVER (PARTITION BY brand ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cost, SUM(cost) OVER (PARTITION BY category ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_cost FROM products;
